let ver;

function setup() {
	frameRate(25);
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	if (mySize > 1000) mySize = 1000;
	margin = mySize / 100;
	createCanvas(mySize * 11 / 16, mySize, WEBGL);
	h = max(width, height) * 1.5;

	strokeJoin(ROUND);
	palette1 = random(colorScheme).colors.concat();
	palette2 = random(colorScheme).colors.concat();
	color_set[0] = random(palette1);
	color_set[1] = random(palette2);
	color_set[2] = random(palette1);
	color_set[3] = random(palette2);
	color_set[4] = random(palette1);
	color_set[5] = random(palette1);
	color_set[6] = random(palette1);
	let bac = lerpColor(color(random(palette1)), color(random(palette2)), 0.5)
	background(bac);

	tempArr = polygonArr(h / 2, h / 2, h / 2.2, 100, 0);
	tempArr.forEach(function(item) {
		points.push(item)
	})

	for (let i = 0; i < 200; i++) {
		let r = sqrt(random(0, (h / random(1, 4.5)) ** 2))
		let ang = random(0, TWO_PI * 1)
		points.push([cos(ang + r) * r + h / 2, sin(ang - r) * r + h / 2]);
	}
	brush.scaleBrushes(1.1);
	brush.field(random(["seabed", "curved", "truncated", "waves"]));

	num_cols = random([1, 2, 3])
	num_rows = random([4, 5, 6])
	border = mySize / 5;

	col_size = (width - border) / num_cols
	row_size = (height - border) / num_rows

	ver = random([1, 2]);
}

function draw() {
	translate(-width / 2, -height / 2);

	let delaunay = Delaunator.from(points);
	let triangles = delaunay.triangles;

	strokeWeight(0)
	push();
	translate((width - h) / 2, (height - h) / 2);
	drawTriangles(triangles)
	pop();
	bgCubes2()

	if (frameCount == 2) {
		noLoop();
		noFill();
		stroke("#202020");
		strokeWeight(mySize / 100);
		blendMode(BLEND);
		rectMode(CORNER);
		rect(0, 0, width, height);
	}

}

function drawTriangles(triangles) {
	let coord = []

	for (let i = 0; i < triangles.length; i += 3) {
		coord.push([
			points[triangles[i]],
			points[triangles[i + 1]],
			points[triangles[i + 2]]
		]);
	}

	for (let i = 0; i < coord.length; i++) {
		let a = coord[i];
		let p0 = a[0];
		let p1 = a[1];
		let p2 = a[2];
		let tx = (p0[0] + p1[0] + p2[0]) / 3;
		let ty = (p0[1] + p1[1] + p2[1]) / 3;

		push();

		fill(random(color_set))

		let stroke_brushes = brush.box()
		brush.set(random(stroke_brushes), random(color_set), random(5, 0.1))

		let border_t = -0.5

		brush.stroke(random(color_set))
		brush.noFill();

		let np1 = createVector(p0[0] - border_t * (p0[0] - tx), p0[1] - border_t * (p0[1] - ty));
		let np2 = createVector(p1[0] - border_t * (p1[0] - tx), p1[1] - border_t * (p1[1] - ty));
		let np3 = createVector(p2[0] - border_t * (p2[0] - tx), p2[1] - border_t * (p2[1] - ty));
		let d1 = p5.Vector.dist(np1, np2);
		let d2 = p5.Vector.dist(np2, np3);
		let d3 = p5.Vector.dist(np1, np3);
		switch (ver) {
			case 1:
				brush.line(p0[0] - border_t * (p0[0] - tx), p0[1] - border_t * (p0[1] - ty),
					p0[0] - border_t * (p0[0] - tx), p1[1] - border_t * (p1[1] - ty));
				brush.line(p1[0] - border_t * (p1[0] - tx), p1[1] - border_t * (p1[1] - ty),
					p1[0] - border_t * (p1[0] - tx), p2[1] - border_t * (p2[1] - ty));
				brush.line(p2[0] - border_t * (p2[0] - tx), p2[1] - border_t * (p2[1] - ty),
					p2[0] - border_t * (p2[0] - tx), p0[1] - border_t * (p0[1] - ty));
				break;
			case 2:
				brush.line(p0[0] - border_t * (p0[0] - tx), p0[1] - border_t * (p0[1] - ty),
					p1[0] - border_t * (p1[0] - tx), p0[1] - border_t * (p0[1] - ty));
				brush.line(p1[0] - border_t * (p1[0] - tx), p1[1] - border_t * (p1[1] - ty),
					p2[0] - border_t * (p2[0] - tx), p1[1] - border_t * (p1[1] - ty));
				brush.line(p2[0] - border_t * (p2[0] - tx), p2[1] - border_t * (p2[1] - ty),
					p0[0] - border_t * (p0[0] - tx), p2[1] - border_t * (p2[1] - ty));
				break;
		}


		noFill();
		stroke(random(color_set));
		strokeWeight(random(0.2))
		circle(p0[0] - border_t * (p0[0] - tx), p0[1] - border_t * (p0[1] - ty), random(2, 20));
		circle(p1[0] - border_t * (p1[0] - tx), p1[1] - border_t * (p1[1] - ty), random(2, 10));
		circle(p2[0] - border_t * (p2[0] - tx), p2[1] - border_t * (p2[1] - ty), random(2, 10));
		pop()
	}
}

function polygonArr(x, y, radius, npoints, angZero) {
	let arr = []
	let angle = TWO_PI / npoints;
	for (let a = angZero; a < TWO_PI + angZero; a += angle) {
		arr.push([x + cos(a) * radius, y + sin(a) * radius])
	}
	return arr
}


function lissajous(x, y, radius, npoints, angZero) {
	var arr = []

	var angle = TWO_PI / npoints;
	for (let a = angZero; a < TWO_PI + angZero; a += angle) {

		arr.push([x + cos(2 * a) * sin(1 * a) * radius, y - sin(1 * a) * cos(1 * a) * radius])
	}
	return arr
}

function polygonDraw(x, y, radius, npoints) {
	var angle = TWO_PI / npoints;
	beginShape();
	for (let a = 0; a < TWO_PI; a += angle) {
		let sx = x + cos(a) * radius;
		let sy = y + sin(a) * radius;
		vertex(sx, sy);
	}
	endShape(CLOSE);
}

function bgCubes2() {
	tileSize = random([100, 60, 80]) * 0.67;
	wNum = int(width / tileSize) + 1;
	hNum = int(height / tileSize) + 1;
	for (let w = 0; w < wNum; w++) {
		for (let h = 0; h < hNum; h++) {
			push();
			translate(-tileSize, -tileSize);
			translate(w * tileSize, h * tileSize);
			noFill();
			stroke(random(color_set));
			strokeWeight(random(1, 0.2));

			switch (ver) {
				case 1:
					if (abs(abs(w) % random([2, 4, 3])) == 0 || abs(abs(h) % random([2, 3])) == 0) {
						line(0, 0, 0, tileSize / random([2, 8, 32, 16, 8, 16, 4, 1, 2, 1]));
					} else {
						line(0, 0, 0, tileSize / random([0.25, 2, 1, 0.5, 4, 8]));
					}
					break;
				case 2:
						if (abs(abs(w) % random([2, 4, 3])) == 0 || abs(abs(h) % random([2, 3])) == 0) {
						line(0, 0, tileSize / random([2, 8, 32, 16, 8, 16, 4, 1, 2, 1]), 0);
					} else {
						line(0, 0, tileSize / random([0.25, 2, 1, 0.5, 4, 8]), 0);
					}
					break;
			}
			pop();
		}
	}
}

